class Solution:
    def countMagicalPairs(self, s: str) -> int:
        answer, n = 0, len(s)
        for split in range(n - 1):
            left_counts = [0] * 27
            seen = set()
            for i in range(split, -1, -1):
                seen.add(s[i]); left_counts[len(seen)] += 1
            right_counts = [0] * 27
            seen.clear()
            for j in range(split + 1, n):
                seen.add(s[j]); right_counts[len(seen)] += 1
            answer += sum(a * b for a, b in zip(left_counts, right_counts))
        return answer
